import java.util.function.DoubleSupplier;

public final class Retry {
    public static double backoffDelay(int attempt, double base, double maxDelay, DoubleSupplier rand) {
        double cap = Math.min(maxDelay, base * Math.pow(2, attempt));
        return rand.getAsDouble() * cap;
    }
}

