public final class RetryTest {
    public static void main(String[] args) {
        checkUpperBoundIsTheCap();
        checkLowerBoundIsZero();
        checkDelayNeverExceedsMaxDelayForLargeAttempts();
        checkStaysInBounds();
        System.out.println("all tests passed");
    }

    static void checkUpperBoundIsTheCap() {
        double delay = Retry.backoffDelay(2, 1, 100, () -> 1.0);
        if (delay != 4) throw new AssertionError("got " + delay + ", want 4");
    }

    static void checkLowerBoundIsZero() {
        double delay = Retry.backoffDelay(5, 1, 100, () -> 0.0);
        if (delay != 0) throw new AssertionError("got " + delay + ", want 0");
    }

    static void checkDelayNeverExceedsMaxDelayForLargeAttempts() {
        double delay = Retry.backoffDelay(50, 1, 10, () -> 1.0);
        if (delay != 10) throw new AssertionError("got " + delay + ", want 10");
    }

    static void checkStaysInBounds() {
        for (int attempt = 0; attempt < 10; attempt++) {
            double delay = Retry.backoffDelay(attempt, 1, 20, () -> 0.5);
            if (delay < 0 || delay > 20) throw new AssertionError("delay out of bounds: " + delay);
        }
    }
}

